import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>
#include <vector>

__global__ void __launch_bounds__(256, 4) max_reduce_kernel(const float* __restrict__ input,
                                   float* __restrict__ output,
                                   long outer_size,
                                   long reduce_size,
                                   long inner_size) {
    const int UNROLL = 4;
    long outer_idx = blockIdx.y;
    if (outer_idx >= outer_size) return;
    long inner_chunks = (inner_size + UNROLL - 1) / UNROLL;
    long chunk_start = blockIdx.x * (long)blockDim.x + threadIdx.x;
    long stride_chunk = (long)blockDim.x * gridDim.x;
    const float* in_base = input + outer_idx * reduce_size * inner_size;
    float* out_base = output + outer_idx * inner_size;
    for (long chunk = chunk_start; chunk < inner_chunks; chunk += stride_chunk) {
        long inner_idx0 = chunk * UNROLL;
        long remaining = inner_size - inner_idx0;
        int valid = remaining < UNROLL ? (int)remaining : UNROLL;
        float max_val0 = -FLT_MAX;
        float max_val1 = -FLT_MAX;
        float max_val2 = -FLT_MAX;
        float max_val3 = -FLT_MAX;
        if (valid == UNROLL && (inner_size % 4 == 0)) {
            #pragma unroll 4
            for (long i = 0; i < reduce_size; ++i) {
                const float4* row4 = reinterpret_cast<const float4*>(in_base + i * inner_size + inner_idx0);
                float4 v = __ldg(row4);
                max_val0 = fmaxf(max_val0, v.x);
                max_val1 = fmaxf(max_val1, v.y);
                max_val2 = fmaxf(max_val2, v.z);
                max_val3 = fmaxf(max_val3, v.w);
            }
            float4 out4;
            out4.x = max_val0;
            out4.y = max_val1;
            out4.z = max_val2;
            out4.w = max_val3;
            *reinterpret_cast<float4*>(out_base + inner_idx0) = out4;
        } else {
            #pragma unroll 4
            for (long i = 0; i < reduce_size; ++i) {
                const float* row = in_base + i * inner_size + inner_idx0;
                float v0 = __ldg(row);
                max_val0 = fmaxf(max_val0, v0);
                if (valid > 1) { float v1 = __ldg(row + 1); max_val1 = fmaxf(max_val1, v1); }
                if (valid > 2) { float v2 = __ldg(row + 2); max_val2 = fmaxf(max_val2, v2); }
                if (valid > 3) { float v3 = __ldg(row + 3); max_val3 = fmaxf(max_val3, v3); }
            }
            out_base[inner_idx0] = max_val0;
            if (valid > 1) out_base[inner_idx0 + 1] = max_val1;
            if (valid > 2) out_base[inner_idx0 + 2] = max_val2;
            if (valid > 3) out_base[inner_idx0 + 3] = max_val3;
        }
    }
}
torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    int ndim = input.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = input.sizes();
    long outer_size = 1;
    for (int i = 0; i < dim; ++i) outer_size *= sizes[i];
    long reduce_size = sizes[dim];
    long inner_size = 1;
    for (int i = dim + 1; i < ndim; ++i) inner_size *= sizes[i];
    std::vector<int64_t> out_sizes;
    for (int i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(sizes[i]);
    }
    auto output = torch::empty(out_sizes, input.options());
    const int UNROLL = 4;
    int threads_x = 256; // threads mapped along inner dimension for coalesced global memory access
    dim3 block(threads_x);
    long inner_chunks_l = (inner_size + UNROLL - 1) / UNROLL;
    long blocks_x_l = (inner_chunks_l + threads_x - 1) / threads_x;
    int blocks_x = (int)(blocks_x_l > 65535 ? 65535 : blocks_x_l);
    if (blocks_x < 1) blocks_x = 1;
    int blocks_y = (int)(outer_size > 65535 ? 65535 : outer_size);
    if (blocks_y < 1) blocks_y = 1;
    dim3 grid(blocks_x, blocks_y);
    max_reduce_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        outer_size, reduce_size, inner_size
    );
    return output;
}
"""
cpp_decl = "torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim);"
max_reduce_module = load_inline(
    name="max_reduce_module",
    cpp_sources=cpp_decl,
    cuda_sources=max_reduce_source,
    functions=["max_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Max reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.max_reduce = max_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        return self.max_reduce.max_reduce_cuda(x, self.dim)


batch_size = 128
dim1 = 4096
dim2 = 4095

def get_inputs():
    x = torch.rand(batch_size, dim1, dim2)
    return [x]

def get_init_inputs():
    return [1]

